import React, { useState, useEffect, useMemo } from 'react';
import { Client, ClientStats, User as UserType } from './types';
import { Plus, Search, Tv, LayoutDashboard, BarChart3, LogOut, X, Settings, Loader2, AlertTriangle, RefreshCw } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { ClientModal } from './components/ClientModal';
import { SettingsModal } from './components/SettingsModal';
import { AnalyticsView } from './components/AnalyticsView';
import { AuthView } from './components/AuthView';
import { auth, authStateListener, logOut } from './services/firebase';

const App: React.FC = () => {
  const [user, setUser] = useState<UserType | null>(null);
  const [loading, setLoading] = useState(true);
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState<'all' | 'active' | 'expiring' | 'expired'>('all');
  const [tab, setTab] = useState<'list' | 'analytics'>('list');
  const [timeoutError, setTimeoutError] = useState(false);

  // Modals
  const [showClientModal, setShowClientModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // --- Auth & Data Loading ---
  useEffect(() => {
    // Timeout de segurança: Se o Firebase demorar mais de 5s, libera o app ou mostra erro
    const safetyTimer = setTimeout(() => {
      if (loading) {
        console.warn("Loading timeout reached. Force releasing...");
        if (!user) {
            setLoading(false); // Libera para AuthView se não logou
        } else {
            setTimeoutError(true); // Mostra erro se estava tentando carregar dados
        }
      }
    }, 5000);

    const unsubscribe = authStateListener(auth, (u: any) => {
      clearTimeout(safetyTimer);
      if (u) {
        setUser({
          id: u.uid,
          username: u.displayName || u.email.split('@')[0],
          email: u.email,
          avatar: u.photoURL
        });
        // Load Data from LocalStorage (Simulated DB)
        try {
          const saved = localStorage.getItem(`iptv_db_${u.uid}`);
          setClients(saved ? JSON.parse(saved) : []);
        } catch (e) {
          console.error("Erro ao carregar dados locais", e);
          setClients([]);
        }
      } else {
        setUser(null);
        setClients([]);
      }
      setLoading(false);
    });

    return () => {
        unsubscribe();
        clearTimeout(safetyTimer);
    };
  }, []);

  // --- Persistence ---
  useEffect(() => {
    if (user) {
      localStorage.setItem(`iptv_db_${user.id}`, JSON.stringify(clients));
    }
  }, [clients, user]);

  // --- Handlers ---
  const handleLogout = async () => {
    await logOut(auth);
    setUser(null);
  };

  const saveClient = (client: Client) => {
    if (editingClient) {
      setClients(prev => prev.map(c => c.id === client.id ? client : c));
    } else {
      setClients(prev => [...prev, client]);
    }
    setShowClientModal(false);
    setEditingClient(null);
  };

  const deleteClient = (id: string) => {
    if (confirm('Tem certeza que deseja remover este cliente?')) {
      setClients(prev => prev.filter(c => c.id !== id));
    }
  };

  const renewClient = (id: string) => {
    setClients(prev => prev.map(c => {
      if (c.id !== id) return c;
      const today = new Date();
      // Reset hours to avoid timezone issues
      today.setHours(0,0,0,0);

      const currentRenewal = new Date(c.renewalDate + 'T00:00:00');

      // If expired, start 30 days from today. If active, add 30 days to current date.
      let baseDate = currentRenewal < today ? today : currentRenewal;
      baseDate.setDate(baseDate.getDate() + 30);

      return { 
        ...c, 
        renewalDate: baseDate.toISOString().split('T')[0] 
      };
    }));
  };

  // --- Derived State ---
  const getDiffDays = (date: string) => {
    const today = new Date();
    today.setHours(0,0,0,0);
    const target = new Date(date + 'T00:00:00');
    return Math.ceil((target.getTime() - today.getTime()) / (86400000));
  };

  const filteredList = useMemo(() => {
    let list = clients;

    // Text Search
    if (searchTerm) {
      const q = searchTerm.toLowerCase();
      list = list.filter(c => 
        c.name.toLowerCase().includes(q) || 
        c.server?.toLowerCase().includes(q) ||
        c.phone.includes(q)
      );
    }

    // Status Filter
    if (filter !== 'all') {
      list = list.filter(c => {
        const days = getDiffDays(c.renewalDate);
        if (filter === 'active') return days > 3;
        if (filter === 'expiring') return days >= 0 && days <= 3;
        if (filter === 'expired') return days < 0;
        return true;
      });
    }

    // Sort by Expiration (Urgent first)
    return list.sort((a, b) => getDiffDays(a.renewalDate) - getDiffDays(b.renewalDate));
  }, [clients, searchTerm, filter]);

  const stats = useMemo(() => {
    let rev = 0, expiring = 0;
    clients.forEach(c => {
      const d = getDiffDays(c.renewalDate);
      if (d > -30) rev += c.price; // Active revenue logic
      if (d >= 0 && d <= 3) expiring++;
    });
    return { totalClients: clients.length, activeRevenue: rev, expiringSoon: expiring };
  }, [clients]);

  // --- RENDER ---
  if (timeoutError) return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-4">
        <AlertTriangle className="text-rose-500 w-12 h-12 mb-4" />
        <h2 className="text-white text-lg font-bold mb-2">O carregamento demorou muito</h2>
        <p className="text-slate-400 mb-6 text-center max-w-xs">Verifique sua conexão ou tente recarregar a página.</p>
        <button onClick={() => window.location.reload()} className="bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2">
            <RefreshCw size={18} /> Recarregar
        </button>
    </div>
  );

  if (loading) return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center">
      <Loader2 className="w-10 h-10 text-indigo-500 animate-spin" />
    </div>
  );

  if (!user) return <AuthView />;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-indigo-500/30">

      {/* Header */}
      <header className="sticky top-0 z-40 glass border-b border-white/5">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 h-16 md:h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-900/30">
              <Tv className="text-white" size={20} />
            </div>
            <div>
              <h1 className="text-lg font-bold text-white tracking-tight leading-none">MANAGER PRO</h1>
              <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">Dashboard v2.0</span>
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <div className="hidden md:flex flex-col items-end mr-2">
              <span className="text-xs font-bold text-slate-400">Olá, {user.username}</span>
              <span className="text-[10px] text-emerald-500 flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> Online
              </span>
            </div>

            <button onClick={() => setShowSettingsModal(true)} className="p-2.5 hover:bg-white/5 rounded-xl transition-colors text-slate-400 hover:text-white">
              <Settings size={20} />
            </button>
            <button onClick={handleLogout} className="p-2.5 hover:bg-rose-500/10 rounded-xl transition-colors text-slate-400 hover:text-rose-400">
              <LogOut size={20} />
            </button>

            <div className="w-px h-8 bg-white/10 mx-1 hidden sm:block"></div>

            <button 
              onClick={() => { setEditingClient(null); setShowClientModal(true); }}
              className="bg-indigo-600 hover:bg-indigo-500 text-white pl-4 pr-5 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition-all shadow-lg shadow-indigo-900/20 active:scale-95"
            >
              <Plus size={16} />
              <span className="hidden sm:inline">NOVO CLIENTE</span>
              <span className="sm:hidden">NOVO</span>
            </button>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 flex gap-6">
          <NavButton active={tab === 'list'} onClick={() => setTab('list')} icon={LayoutDashboard} label="Painel Geral" />
          <NavButton active={tab === 'analytics'} onClick={() => setTab('analytics')} icon={BarChart3} label="Analytics" />
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 py-8 pb-24">
        {tab === 'list' ? (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <StatsCards stats={stats} />

            {/* Filters Bar */}
            <div className="flex flex-col md:flex-row gap-4 items-start md:items-center justify-between bg-slate-900/40 p-2 rounded-2xl border border-white/5">
              <div className="relative w-full md:w-96 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-400 transition-colors" size={18} />
                <input 
                  type="text" 
                  placeholder="Buscar clientes..." 
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                  className="w-full bg-slate-950/50 border border-white/5 rounded-xl pl-11 pr-4 py-3 text-sm text-white focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500/40 outline-none transition-all"
                />
                {searchTerm && (
                  <button onClick={() => setSearchTerm('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white p-1">
                    <X size={14} />
                  </button>
                )}
              </div>

              <div className="flex gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0 scrollbar-hide">
                <FilterChip active={filter === 'all'} onClick={() => setFilter('all')} label="Todos" count={clients.length} color="slate" />
                <FilterChip active={filter === 'active'} onClick={() => setFilter('active')} label="Ativos" count={clients.filter(c => getDiffDays(c.renewalDate) > 3).length} color="emerald" />
                <FilterChip active={filter === 'expiring'} onClick={() => setFilter('expiring')} label="A vencer" count={clients.filter(c => { const d = getDiffDays(c.renewalDate); return d >= 0 && d <= 3 }).length} color="amber" />
                <FilterChip active={filter === 'expired'} onClick={() => setFilter('expired')} label="Vencidos" count={clients.filter(c => getDiffDays(c.renewalDate) < 0).length} color="rose" />
              </div>
            </div>

            {/* Grid */}
            {filteredList.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
                {filteredList.map(client => (
                  <ClientCard 
                    key={client.id} 
                    client={client} 
                    daysUntilExpiration={getDiffDays(client.renewalDate)}
                    onDelete={deleteClient}
                    onEdit={(c) => { setEditingClient(c); setShowClientModal(true); }}
                    onRenew={renewClient}
                  />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-slate-500 border-2 border-dashed border-slate-800 rounded-3xl bg-slate-900/20">
                <Search size={48} className="mb-4 opacity-50" />
                <p className="text-lg font-medium">Nenhum cliente encontrado</p>
                <p className="text-sm opacity-60">Tente ajustar seus filtros ou adicione um novo.</p>
              </div>
            )}
          </div>
        ) : (
          <AnalyticsView clients={clients} />
        )}
      </main>

      {/* Modals */}
      <ClientModal 
        isOpen={showClientModal} 
        onClose={() => setShowClientModal(false)} 
        onSave={saveClient} 
        editingClient={editingClient} 
      />

      <SettingsModal
        isOpen={showSettingsModal}
        onClose={() => setShowSettingsModal(false)}
        clients={clients}
        onImportClients={setClients}
      />
    </div>
  );
};

