    if (loggedUser) {
      const storageKey = `iptv_data_user_${loggedUser.id}`;
      localStorage.setItem(storageKey, JSON.stringify(clients));
    }
  }, [clients, loggedUser]);

  const handleLogout = useCallback(async () => {
    try {
      await signOut(auth);
      setLoggedUser(null);
    } catch (error) {
      console.error("Erro ao sair:", error);
    }
  }, []);

  const handleRenewClient = useCallback((id: string) => {
    setClients(prev => prev.map(client => {
      if (client.id !== id) return client;
      const today = new Date();
      const currentRenewal = new Date(client.renewalDate);
      let newDate = currentRenewal < today ? new Date(today) : new Date(currentRenewal);
      newDate.setDate(newDate.getDate() + 30);
      return { ...client, renewalDate: newDate.toISOString() };
    }));
  }, []);

  const handleDeleteClient = useCallback((id: string) => {
    if (confirm('Excluir este cliente?')) {
      setClients(prev => prev.filter(c => c.id !== id));
    }
  }, []);

  const handleEditClient = useCallback((c: Client) => {
    setEditingClient(c);
    setIsModalOpen(true);
  }, []);

  const handleSaveClient = useCallback((c: Client) => {
    if (editingClient) {
      setClients(prev => prev.map(cl => cl.id === c.id ? c : cl));
    } else {
      setClients(prev => [...prev, c]);
    }
  }, [editingClient]);

  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;
    clients.forEach(c => {
      revenue += c.price;
      const days = getDaysDifference(c.renewalDate);
      if (days >= 0 && days <= 3) expiring++;
    });
    return { totalClients: clients.length, activeRevenue: revenue, expiringSoon: expiring };
  }, [clients]);

  const counts = useMemo(() => {
    const counts = { all: clients.length, active: 0, expiring: 0, expired: 0 };
    clients.forEach(c => {
      const days = getDaysDifference(c.renewalDate);
      if (days < 0) counts.expired++;
      else if (days <= 3) counts.expiring++;
      else counts.active++;
    });
    return counts;
  }, [clients]);

  const filteredClients = useMemo(() => {
    const query = debouncedSearchTerm.toLowerCase();
    return clients
      .filter(c => {
        if (query) {
          const matchesSearch = c.name.toLowerCase().includes(query) || 
                               c.server?.toLowerCase().includes(query) ||
                               c.phone.includes(query) ||
                               c.macAddress?.toLowerCase().includes(query);
          if (!matchesSearch) return false;
        }
        const days = getDaysDifference(c.renewalDate);
        if (filterStatus === 'active') return days > 3;
        if (filterStatus === 'expiring') return days >= 0 && days <= 3;
        if (filterStatus === 'expired') return days < 0;
        return true;
      })
      .sort((a, b) => getDaysDifference(a.renewalDate) - getDaysDifference(b.renewalDate));
  }, [clients, debouncedSearchTerm, filterStatus]);

  if (loadingAuth) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!loggedUser) {
    return (
      <Suspense fallback={<div className="min-h-screen bg-[#020617]" />}>
        <AuthView />
      </Suspense>
    );
  }

  return (
    <div id="conteudo-sistema" className="min-h-screen bg-[#020617] text-slate-200 pb-safe">
      <header className="sticky top-0 z-40 glass border-b border-white/5 pt-[env(safe-area-inset-top)]">
        <div className="max-w-7xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 md:w-10 md:h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-900/40">
              <Tv className="text-white" size={18} />
            </div>
            <div className="hidden xs:block">
              <h1 className="text-base md:text-lg font-black tracking-tighter text-white">MANAGER PRO</h1>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-[0.2em]">Dashboard</p>
            </div>
          </div>

          <div className="flex items-center gap-3 md:gap-6">
            <div className="flex items-center gap-3 pl-3 md:pl-0 border-l md:border-l-0 border-white/5">
               <div className="text-right hidden sm:block">
                 <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest leading-none mb-1">Conta Ativa</p>
                 <p id="user-name" className="text-xs font-bold text-white leading-none truncate max-w-[120px]">{loggedUser.username}</p>
               </div>
               {loggedUser.avatar ? (
                 <img src={loggedUser.avatar} alt="Avatar" className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-indigo-500/30 object-cover shadow-lg" />
               ) : (
                 <div className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-slate-800 border border-white/10 flex items-center justify-center overflow-hidden">
                    <img src={`https://ui-avatars.com/api/?name=${loggedUser.username}&background=4f46e5&color=fff&bold=true`} alt={loggedUser.username} className="w-full h-full object-cover" />
                 </div>
               )}
            </div>

            <div className="flex items-center gap-1">
              <button onClick={handleLogout} className="p-2 text-slate-400 hover:text-rose-400 transition-colors" title="Sair">
                <LogOut size={20} />
              </button>
              <button 
                onClick={() => { setEditingClient(null); setIsModalOpen(true); }} 
                className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2.5 rounded-xl md:rounded-2xl text-[10px] md:text-xs font-black flex items-center gap-2 transition-all active:scale-90 shadow-xl shadow-indigo-900/20"
              >
                <Plus size={16} />
                <span className="hidden sm:inline">NOVO CLIENTE</span>
                <span className="sm:hidden">NOVO</span>
              </button>
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 flex overflow-x-auto scrollbar-hide scroll-ios">
          <button onClick={() => setActiveTab('list')} className={`flex-shrink-0 flex items-center gap-2 px-6 py-4 text-[10px] md:text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'list' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <LayoutDashboard size={14} /> Painel
            {activeTab === 'list' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-500 rounded-full shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
          <button onClick={() => setActiveTab('analytics')} className={`flex-shrink-0 flex items-center gap-2 px-6 py-4 text-[10px] md:text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'analytics' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <BarChart3 size={14} /> Analytics
            {activeTab === 'analytics' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-500 rounded-full shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 md:px-6 py-6 md:py-10 animate-fade-up scroll-ios">
        <Suspense fallback={<LoadingSpinner />}>
          {activeTab === 'list' ? (
            <>
              <StatsCards stats={stats} />
              <div className="space-y-4 md:space-y-6 mb-8 md:mb-12">
                <div className="relative group">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-500 transition-colors" size={18} />
                  <input 
                    type="text" 
                    placeholder="Pesquisar por nome, MAC ou telefone..." 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    className="w-full bg-slate-900/50 border border-white/5 text-white rounded-2xl md:rounded-[24px] pl-12 pr-12 py-4 md:py-5 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500/30 outline-none transition-all text-base font-medium shadow-inner" 
                  />
                  {searchTerm && (
                    <button onClick={() => setSearchTerm('')} className="absolute right-4 top-1/2 -translate-y-1/2 bg-white/5 hover:bg-white/10 p-2 rounded-xl transition-all">
                      <X size={14} className="text-slate-400" />
                    </button>
                  )}
                </div>

                <div className="flex flex-nowrap overflow-x-auto gap-2 md:gap-3 items-center p-1.5 rounded-[20px] md:rounded-[24px] bg-slate-900/40 border border-white/5 scrollbar-hide scroll-ios">
                  <FilterTab active={filterStatus === 'all'} onClick={() => setFilterStatus('all')} label="Todos" count={counts.all} color="indigo" />
                  <FilterTab active={filterStatus === 'active'} onClick={() => setFilterStatus('active')} label="Ativos" count={counts.active} color="emerald" />
                  <FilterTab active={filterStatus === 'expiring'} onClick={() => setFilterStatus('expiring')} label="Aviso" count={counts.expiring} color="amber" />
                  <FilterTab active={filterStatus === 'expired'} onClick={() => setFilterStatus('expired')} label="Fim" count={counts.expired} color="rose" />
                </div>
              </div>

              {filteredClients.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
                  {filteredClients.map(client => (
                    <ClientCard 
                      key={client.id} 
                      client={client} 
                      daysUntilExpiration={getDaysDifference(client.renewalDate)} 
                      onDelete={handleDeleteClient} 
                      onEdit={handleEditClient}
                      onRenew={handleRenewClient}
                    />
                  ))}
                </div>
              ) : (
                <div className="text-center py-16 md:py-24 glass rounded-[32px] md:rounded-[40px] border-dashed border-2 border-white/5">
                  <div className="w-16 h-16 md:w-20 md:h-20 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-6">
                    <Search size={24} className="text-slate-500" />
                  </div>
                  <h3 className="text-xl md:text-2xl font-bold text-white mb-3">Nenhum registro</h3>
                  <p className="text-slate-500 max-w-xs mx-auto text-sm">Ajuste seus filtros ou adicione um novo cliente.</p>
                </div>
              )}
            </>
          ) : <AnalyticsView clients={clients} />}
        </Suspense>
      </main>

      <div className="h-[env(safe-area-inset-bottom)]"></div>

      <Suspense fallback={null}>
        <ClientModal 
          isOpen={isModalOpen} 
          onClose={() => setIsModalOpen(false)} 
          onSave={handleSaveClient} 
          editingClient={editingClient} 
        />
      </Suspense>
    </div>
  );
};

const FilterTab = React.memo(({ active, onClick, label, count, color }: {active: boolean, onClick: () => void, label: string, count: number, color: string}) => {
  const colorMap: any = {
    indigo: active ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:bg-white/5',
    emerald: active ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:bg-white/5',
    amber: active ? 'bg-amber-600 text-white' : 'text-slate-500 hover:bg-white/5',
    rose: active ? 'bg-rose-600 text-white' : 'text-slate-500 hover:bg-white/5'
  };
  return (
    <button onClick={onClick} className={`flex-shrink-0 flex items-center gap-2 px-4 md:px-6 py-2 md:py-3 rounded-xl md:rounded-2xl text-[9px] md:text-[11px] font-black uppercase tracking-widest transition-all ${colorMap[color]} active:scale-95`}>
      {label}
      <span className={`px-1.5 py-0.5 rounded-lg ${active ? 'bg-black/20' : 'bg-slate-800'}`}>{count}</span>
    </button>
  );
});

export default App;

import React, { useState, useEffect, memo } from 'react';
import { Client } from '../types';
import { Calendar, Smartphone, DollarSign, MessageCircle, Trash2, Edit, Wand2, Copy, Check, UserCheck, Clock, AlertCircle, StickyNote, ExternalLink, Zap, Cpu, Key } from 'lucide-react';
import { generateRenewalMessage } from '../services/geminiService';

interface ClientCardProps {
  client: Client;
  daysUntilExpiration: number;
  onDelete: (id: string) => void;
  onEdit: (client: Client) => void;
  onRenew: (id: string) => void;
}

export const ClientCard: React.FC<ClientCardProps> = memo(({ client, daysUntilExpiration, onDelete, onEdit, onRenew }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedMsg, setGeneratedMsg] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [successAnimation, setSuccessAnimation] = useState(false);

  const [macCopied, setMacCopied] = useState(false);
  const [passCopied, setPassCopied] = useState(false);

  useEffect(() => {
    if (successAnimation) {
      const timer = setTimeout(() => setSuccessAnimation(false), 2500);
      return () => clearTimeout(timer);
    }
  }, [successAnimation]);

  let statusTheme = {
    border: "border-emerald-500/20 hover:border-emerald-500/40",
    bg: "bg-emerald-500/5",
    badge: "bg-emerald-500/10 text-emerald-400",
    text: "Ativo",
    icon: UserCheck
  };

  if (daysUntilExpiration < 0) {
    statusTheme = {
      border: "border-rose-500/20 hover:border-rose-500/40",
      bg: "bg-rose-500/5",
      badge: "bg-rose-500/10 text-rose-400",
      text: "Vencido",
      icon: AlertCircle
    };
  } else if (daysUntilExpiration <= 3) {
    statusTheme = {
      border: "border-amber-500/20 hover:border-amber-500/40",
      bg: "bg-amber-500/5",
      badge: "bg-amber-500/10 text-amber-400",
      text: "Vencendo",
      icon: Clock
    };
  }

  const handleGenerateMessage = async () => {
    setIsGenerating(true);
    setGeneratedMsg(null);
    const msg = await generateRenewalMessage(client);
    setGeneratedMsg(msg);
    setIsGenerating(false);
  };

  const copyToClipboard = () => {
    if (generatedMsg) {
      navigator.clipboard.writeText(generatedMsg);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const copyField = (text: string, setter: React.Dispatch<React.SetStateAction<boolean>>) => {
      navigator.clipboard.writeText(text);
      setter(true);
      setTimeout(() => setter(false), 1500);
  };

  const handleRenewClick = () => {
    setSuccessAnimation(true);
    onRenew(client.id);
  };

  const sendWhatsApp = () => {
    if (!client.phone) return;
    const cleanPhone = client.phone.replace(/\D/g, '');
    const text = generatedMsg ? encodeURIComponent(generatedMsg) : "";
    window.open(`https://wa.me/55${cleanPhone}?text=${text}`, '_blank');
  };

  return (
    <div className={`glass rounded-3xl border ${successAnimation ? 'border-emerald-500/60 shadow-[0_0_30px_rgba(16,185,129,0.2)]' : statusTheme.border} p-6 transition-all duration-300 group hover:shadow-2xl relative overflow-hidden animate-fade-up`}>
      {successAnimation && <div className="absolute inset-0 bg-emerald-500/10 animate-pulse z-0 pointer-events-none" />}

      <div className="flex justify-between items-start mb-6 relative z-10">
        <div className="flex gap-4">
          <div className={`p-3 rounded-2xl ${successAnimation ? 'bg-emerald-500/20 text-emerald-400' : statusTheme.bg} border border-white/5 text-white/80 transition-colors duration-500`}>
             {successAnimation ? <Check size={24} /> : <statusTheme.icon size={24} />}
          </div>
          <div>
            <h3 className="text-xl font-bold text-white tracking-tight leading-tight truncate max-w-[160px]">
              {client.name}
            </h3>
            <span className={`inline-block mt-1 text-[10px] uppercase font-black px-2 py-0.5 rounded-full transition-colors duration-500 ${successAnimation ? 'bg-emerald-500/20 text-emerald-400' : statusTheme.badge}`}>
              {successAnimation ? "RENOVADO" : statusTheme.text}
            </span>
          </div>
        </div>

        <div className="flex gap-1">
          <button onClick={() => onEdit(client)} className="p-2 text-slate-500 hover:text-white hover:bg-white/5 rounded-xl transition-all" title="Editar">
            <Edit size={18} />
          </button>
          <button onClick={() => onDelete(client.id)} className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-400/5 rounded-xl transition-all" title="Excluir">
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="space-y-3 mb-6 relative z-10 text-sm">
        <div className="flex items-center justify-between">
          <span className="text-slate-500 font-medium flex items-center gap-2"><Calendar size={14} /> Expiração</span>
          <span className={`font-semibold transition-colors duration-500 ${successAnimation ? 'text-emerald-400 scale-105 origin-right' : 'text-slate-200'}`}>
            {new Date(client.renewalDate).toLocaleDateString('pt-BR')}
          </span>
        </div>
        <div className="flex items-center justify-between">
          <span className="text-slate-500 font-medium flex items-center gap-2"><DollarSign size={14} /> Valor</span>
          <span className="text-emerald-400 font-bold">R$ {client.price.toFixed(2)}</span>
        </div>
        <div className="flex items-center justify-between">
          <span className="text-slate-500 font-medium flex items-center gap-2"><Smartphone size={14} /> Telas</span>
          <span className="text-slate-200 font-semibold">{client.devices} dispositivo(s)</span>
        </div>
        {client.server && (
          <div className="flex items-center justify-between">
            <span className="text-slate-500 font-medium flex items-center gap-2"><ExternalLink size={14} /> Servidor</span>
            <span className="text-indigo-400 font-semibold px-2 py-0.5 bg-indigo-500/10 rounded-lg border border-indigo-500/20 uppercase text-[10px]">{client.server}</span>
          </div>
        )}
      </div>

      {(client.macAddress || client.devicePassword) && (
        <div className="mb-6 p-3 bg-slate-900/50 rounded-2xl border border-white/5 space-y-2 relative z-10">
          {client.macAddress && (
            <div className="flex items-center justify-between group/mac">
               <div className="flex items-center gap-2 text-slate-500">
                  <Cpu size={14} />
                  <span className="text-[10px] font-black uppercase tracking-wider">MAC</span>
               </div>
               <button onClick={() => copyField(client.macAddress!, setMacCopied)} className="flex items-center gap-2 text-xs font-mono text-slate-300 hover:text-white transition-colors">
                 {client.macAddress}
                 {macCopied ? <Check size={12} className="text-emerald-400"/> : <Copy size={12} className="opacity-0 group-hover/mac:opacity-100 transition-opacity"/>}
               </button>
            </div>
          )}
          {client.devicePassword && (
            <div className="flex items-center justify-between group/pass">
               <div className="flex items-center gap-2 text-slate-500">
                  <Key size={14} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Senha</span>
               </div>
               <button onClick={() => copyField(client.devicePassword!, setPassCopied)} className="flex items-center gap-2 text-xs font-medium text-slate-300 hover:text-white transition-colors">
                 {client.devicePassword}
                 {passCopied ? <Check size={12} className="text-emerald-400"/> : <Copy size={12} className="opacity-0 group-hover/pass:opacity-100 transition-opacity"/>}
               </button>
            </div>
          )}
        </div>
      )}

      {client.notes && (
        <div className="mb-6 p-3.5 bg-slate-950/40 rounded-2xl border border-white/5 flex gap-3 relative z-10">
          <StickyNote size={14} className="text-indigo-500 shrink-0 mt-1" />
          <p className="text-xs text-slate-400 italic leading-relaxed line-clamp-2 hover:line-clamp-none transition-all">{client.notes}</p>
        </div>
      )}

      <div className="pt-4 border-t border-white/5 space-y-3 relative z-10">
        {(daysUntilExpiration <= 3 && !successAnimation) ? (
          <button onClick={handleRenewClick} className="w-full bg-gradient-to-r from-emerald-500 to-teal-600 hover:from-emerald-400 hover:to-teal-500 text-white py-3.5 rounded-2xl flex items-center justify-center gap-2 text-sm font-black uppercase tracking-wider transition-all shadow-xl shadow-emerald-900/30 active:scale-[0.98] animate-pulse">
            <Zap size={18} fill="currentColor" /> RENOVAR AGORA
          </button>
        ) : successAnimation ? (
           <div className="w-full bg-emerald-500/20 border border-emerald-500/30 text-emerald-400 py-3 rounded-2xl flex items-center justify-center gap-2 text-sm font-bold animate-in fade-in zoom-in-95 duration-300">
              <Check size={18} /> Renovado com Sucesso!
           </div>
        ) : null}

        {!generatedMsg && !successAnimation && (
           <div className="flex gap-2">
             <button onClick={handleGenerateMessage} disabled={isGenerating} className="flex-1 bg-slate-800 hover:bg-slate-700 text-white py-3 px-4 rounded-2xl flex items-center justify-center gap-2 text-xs font-bold transition-all disabled:opacity-50 active:scale-[0.97]">
               {isGenerating ? <span className="animate-pulse">Criando...</span> : <><Wand2 size={14} /> Cobrança IA</>}
             </button>
              <button onClick={() => {
                  const cleanPhone = client.phone.replace(/\D/g, '');
                  window.open(`https://wa.me/55${cleanPhone}`, '_blank');
                }} className="bg-emerald-600 hover:bg-emerald-500 text-white p-3 rounded-2xl transition-all active:scale-[0.97]" title="Abrir WhatsApp">
                <MessageCircle size={20} />
              </button>
           </div>
        )}

        {generatedMsg && !successAnimation && (
          <div className="bg-slate-900/80 rounded-2xl p-4 border border-indigo-500/20 animate-in fade-in zoom-in-95">
            <p className="text-slate-300 text-xs whitespace-pre-line mb-4 border-l-2 border-indigo-500 pl-3 italic">{generatedMsg}</p>
            <div className="flex flex-wrap gap-2">
              <button onClick={copyToClipboard} className="flex-1 bg-white/10 hover:bg-white/20 text-white py-2 rounded-xl flex items-center justify-center gap-2 text-[11px] font-bold transition-all">
                {copied ? <Check size={14} className="text-emerald-400" /> : <Copy size={14} />}
                {copied ? "Pronto!" : "Copiar"}
              </button>
              <button onClick={sendWhatsApp} className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white py-2 rounded-xl flex items-center justify-center gap-2 text-[11px] font-bold transition-all">
                <MessageCircle size={14} /> Enviar
              </button>
              <button onClick={() => setGeneratedMsg(null)} className="w-full mt-2 text-slate-500 hover:text-white text-[10px] font-bold uppercase tracking-widest text-center">Cancelar</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}));

import React, { memo } from 'react';
import { Users, DollarSign, AlertTriangle } from 'lucide-react';
import { ClientStats } from '../types';

interface StatsCardsProps {
  stats: ClientStats;
}

export const StatsCards: React.FC<StatsCardsProps> = memo(({ stats }) => {
  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
      <StatItem 
        icon={<Users size={22} />}
        label="Total de Clientes"
        value={stats.totalClients}
        color="indigo"
      />
      <StatItem 
        icon={<DollarSign size={22} />}
        label="Receita Mensal"
        value={`R$ ${stats.activeRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
        color="emerald"
      />
      <StatItem 
        icon={<AlertTriangle size={22} />}
        label="Vencem em breve"
        value={stats.expiringSoon}
        color="orange"
      />
    </div>
  );
});

const StatItem = ({ icon, label, value, color }: { icon: any, label: string, value: string | number, color: 'indigo' | 'emerald' | 'orange' }) => {
