import React, { useState, useMemo, memo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  ComposedChart, Line
} from 'recharts';
import { Client } from '../types';
import { TrendingUp, Users, DollarSign, UserPlus, Calendar, ArrowUpRight, ArrowDownRight } from 'lucide-react';

interface AnalyticsViewProps {
  clients: Client[];
}

export const AnalyticsView: React.FC<AnalyticsViewProps> = memo(({ clients }) => {
  const [timeRange, setTimeRange] = useState<number>(12);

  const monthlyData = useMemo(() => {
    const data = [];
    const today = new Date();
    for (let i = timeRange - 1; i >= 0; i--) {
      const targetDate = new Date(today.getFullYear(), today.getMonth() - i, 1);
      const monthKey = targetDate.toLocaleDateString('pt-BR', { month: 'short', year: '2-digit' });
      const monthStart = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
      const monthEnd = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0);

      let monthlyRevenue = 0;
      let activeCount = 0;
      let newCount = 0;
      let recurringCount = 0;

      clients.forEach(client => {
        const clientStart = new Date(client.startDate + 'T00:00:00'); 
        const clientEnd = new Date(client.renewalDate + 'T00:00:00');
        const isActiveInMonth = clientStart <= monthEnd && clientEnd >= monthStart;
        if (isActiveInMonth) {
          monthlyRevenue += client.price;
          activeCount++;
          if (clientStart >= monthStart && clientStart <= monthEnd) newCount++;
          else recurringCount++;
        }
      });

      data.push({ name: monthKey, receita: monthlyRevenue, totalClientes: activeCount, novos: newCount, recorrentes: recurringCount });
    }
    return data;
  }, [clients, timeRange]);

  const currentMonth = monthlyData[monthlyData.length - 1];
  const previousMonth = monthlyData[monthlyData.length - 2];

  const calculateGrowth = (current: number, previous: number) => {
    if (!previous) return 0;
    return ((current - previous) / previous) * 100;
  };

  const revenueGrowth = calculateGrowth(currentMonth.receita, previousMonth?.receita || 0);
  const clientsGrowth = calculateGrowth(currentMonth.totalClientes, previousMonth?.totalClientes || 0);

  return (
    <div className="space-y-8 animate-fade-up pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-extrabold text-white tracking-tight">Analytics Financeiro</h2>
          <p className="text-slate-500 text-sm">Visão detalhada de receita e retenção.</p>
        </div>
        <div className="flex bg-slate-900 p-1 rounded-xl border border-white/10">
          <button onClick={() => setTimeRange(6)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${timeRange === 6 ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>6 Meses</button>
          <button onClick={() => setTimeRange(12)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${timeRange === 12 ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>12 Meses</button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
        <KPICard title="Receita (Mês)" value={`R$ ${currentMonth.receita.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} subValue={`${revenueGrowth > 0 ? '+' : ''}${revenueGrowth.toFixed(1)}% vs anterior`} trend={revenueGrowth >= 0 ? 'up' : 'down'} icon={<DollarSign size={20}/>} color="emerald" />
        <KPICard title="Clientes Ativos" value={currentMonth.totalClientes.toString()} subValue={`${clientsGrowth > 0 ? '+' : ''}${clientsGrowth.toFixed(1)}% vs anterior`} trend={clientsGrowth >= 0 ? 'up' : 'down'} icon={<Users size={20}/>} color="indigo" />
        <KPICard title="Novos" value={currentMonth.novos.toString()} subValue="Este mês" trend="neutral" icon={<UserPlus size={20}/>} color="blue" />
        <KPICard title="Recorrentes" value={currentMonth.recorrentes.toString()} subValue="Fidelizados" trend="neutral" icon={<TrendingUp size={20}/>} color="amber" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-slate-900/50 border border-white/5 p-6 rounded-[24px] shadow-xl">
          <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-6"><DollarSign className="text-emerald-400" size={18} /> Evolução de Receita</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={monthlyData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} tickFormatter={(val) => `R$${val}`} />
                <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '12px' }} itemStyle={{ color: '#fff', fontSize: '12px' }} />
                <Bar dataKey="receita" fill="#10b981" radius={[4, 4, 0, 0]} barSize={24} />
                <Line type="monotone" dataKey="receita" stroke="#34d399" strokeWidth={2} dot={{ r: 3 }} />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-slate-900/50 border border-white/5 p-6 rounded-[24px] shadow-xl">
          <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-6"><Users className="text-indigo-400" size={18} /> Novos vs Recorrentes</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlyData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '12px' }} itemStyle={{ color: '#fff', fontSize: '12px' }} />
                <Bar dataKey="recorrentes" stackId="a" fill="#334155" radius={[0, 0, 4, 4]} barSize={24} name="Recorrentes" />
                <Bar dataKey="novos" stackId="a" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={24} name="Novos" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
});

const KPICard = memo(({ title, value, subValue, icon, color, trend }: { title: string, value: string, subValue: string, icon: any, color: string, trend: 'up' | 'down' | 'neutral' }) => {
  const colors: any = {
    emerald: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
    indigo: "bg-indigo-500/10 text-indigo-400 border-indigo-500/20",
    blue: "bg-blue-500/10 text-blue-400 border-blue-500/20",
    amber: "bg-amber-500/10 text-amber-400 border-amber-500/20"
  };
  const trendIcon = trend === 'up' ? <ArrowUpRight size={14} className="text-emerald-500" /> : trend === 'down' ? <ArrowDownRight size={14} className="text-rose-500" /> : null;
  const trendColor = trend === 'up' ? 'text-emerald-500' : trend === 'down' ? 'text-rose-500' : 'text-slate-500';

  return (
    <div className={`glass p-5 rounded-2xl border ${colors[color]} hover:scale-[1.02] transition-transform`}>
      <div className="flex justify-between items-start mb-4">
        <div>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">{title}</p>
          <h3 className="text-2xl font-extrabold text-white tracking-tight">{value}</h3>
        </div>
        <div className={`p-2.5 rounded-xl ${colors[color].split(' ')[0]} ${colors[color].split(' ')[1]}`}>{icon}</div>
      </div>
      <div className={`flex items-center gap-1 text-[10px] font-bold ${trendColor}`}>
        {trendIcon} <span>{subValue}</span>
      </div>
    </div>
  );
});

