import React, { useState, useEffect, useMemo, useCallback, Suspense, lazy } from 'react';
import { Client, ClientStats, User as UserType } from './types';
import { Plus, Search, Tv, LayoutDashboard, BarChart3, LogOut, X, Loader2, Cloud } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { supabase } from './services/supabase';
import { 
  auth, 
  onAuthStateChanged, 
  signOut, 
  db, 
  doc, 
  getDoc, 
  setDoc,
  collection,
  query,
  onSnapshot,
  updateDoc,
  deleteDoc,
  writeBatch
} from './services/firebase';
import { UserProfileModal } from './components/UserProfileModal';

// Lazy loading components
const ClientModal = lazy(() => import('./components/ClientModal').then(m => ({ default: m.ClientModal })));
const AnalyticsView = lazy(() => import('./components/AnalyticsView').then(m => ({ default: m.AnalyticsView })));
const AuthView = lazy(() => import('./components/AuthView').then(m => ({ default: m.AuthView })));

const getDaysDifference = (dateString: string): number => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const targetDate = new Date(dateString);
  targetDate.setHours(0, 0, 0, 0);
  const diffTime = targetDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const LoadingSpinner = () => (
  <div className="flex flex-col items-center justify-center py-20 gap-4">
    <Loader2 size={32} className="text-indigo-500 animate-spin" />
    <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Sincronizando dados...</p>
  </div>
);

const App: React.FC = () => {
  const [loggedUser, setLoggedUser] = useState<UserType | null>(null);
  const [loadingAuth, setLoadingAuth] = useState(true);
  const [loadingData, setLoadingData] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'expiring' | 'expired'>('all');

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearchTerm(searchTerm);
    }, 300);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  // 1. Monitoramento de Autenticação
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user: any) => {
      if (user) {
        try {
          const userRef = doc(db, "users", user.uid);
          const userSnap = await getDoc(userRef);

          if (userSnap.exists()) {
            const userData = userSnap.data();
            setLoggedUser({
              id: user.uid,
              username: userData.username || user.displayName || 'User',
              email: userData.email || user.email || '',
              avatar: userData.photoURL || user.photoURL || undefined
            });
          } else {
            const newUserData = {
              username: user.displayName || user.email?.split('@')[0] || 'User',
              email: user.email,
              photoURL: user.photoURL,
              createdAt: new Date().toISOString()
            };
            await setDoc(userRef, newUserData);
            setLoggedUser({
              id: user.uid,
              username: newUserData.username,
              email: newUserData.email,
              avatar: newUserData.photoURL || undefined
            });
          }
        } catch (error) {
          console.error("Error fetching user data:", error);
          setLoggedUser({
            id: user.uid,
            username: user.displayName || 'User',
            email: user.email || '',
            avatar: user.photoURL || undefined
          });
        }
      } else {
        setLoggedUser(null);
        setClients([]);
      }
      setLoadingAuth(false);
    });

    return () => unsubscribe();
  }, []);

  // 2. Sincronização em Tempo Real (Firestore) + Migração de LocalStorage
  useEffect(() => {
    if (!loggedUser) return;

    setLoadingData(true);

    // Referência à coleção de clientes deste usuário
    const clientsRef = collection(db, 'users', loggedUser.id, 'clients');
    const q = query(clientsRef);

    // Listener em tempo real
    const unsubscribe = onSnapshot(q, async (snapshot) => {
      const firebaseClients = snapshot.docs.map(doc => ({ 
        id: doc.id, 
        ...doc.data() 
      })) as Client[];

      // LÓGICA DE MIGRAÇÃO: Se o Firestore estiver vazio, verificar LocalStorage
      if (firebaseClients.length === 0) {
        const storageKey = `iptv_data_user_${loggedUser.id}`;
        const localData = localStorage.getItem(storageKey);

        if (localData) {
          try {
            const parsedLocalClients = JSON.parse(localData) as Client[];
            if (parsedLocalClients.length > 0) {
              console.log("Migrando dados do LocalStorage para Firestore...", parsedLocalClients.length);

              // Batch write para eficiência
              const batch = writeBatch(db);
              parsedLocalClients.forEach(client => {
                const docRef = doc(clientsRef, client.id); // Usa o mesmo ID
                batch.set(docRef, client);
              });

              await batch.commit();
              console.log("Migração concluída com sucesso!");

              // Opcional: Limpar localStorage após migração bem sucedida para evitar duplicatas futuras se a lógica mudar
              // localStorage.removeItem(storageKey); 
            }
          } catch (e) {
            console.error("Erro ao migrar dados locais:", e);
          }
        }
      }

      setClients(firebaseClients);
      setLoadingData(false);
    }, (error) => {
      console.error("Erro no listener do Firestore:", error);
      setLoadingData(false);
    });

    return () => unsubscribe();
  }, [loggedUser]);

  const handleLogout = useCallback(async () => {
    try {
      await signOut(auth);
      setLoggedUser(null);
    } catch (error) {
      console.error("Erro ao sair:", error);
    }
  }, []);

  const handleRenewClient = useCallback(async (id: string) => {
    if (!loggedUser) return;

    const clientToRenew = clients.find(c => c.id === id);
    if (!clientToRenew) return;

    const today = new Date();
    const currentRenewal = new Date(clientToRenew.renewalDate);
    let newDate = currentRenewal < today ? new Date(today) : new Date(currentRenewal);
    newDate.setDate(newDate.getDate() + 30);
    const newDateStr = newDate.toISOString().split('T')[0];

    try {
      // Atualiza diretamente no Firestore
      const clientRef = doc(db, 'users', loggedUser.id, 'clients', id);
      await updateDoc(clientRef, { renewalDate: newDateStr });
    } catch (error) {
      console.error("Erro ao renovar cliente:", error);
      alert("Erro ao salvar renovação. Verifique sua conexão.");
    }
  }, [clients, loggedUser]);

  const handleDeleteClient = useCallback(async (id: string) => {
    if (!loggedUser) return;

    // Otimista: remove da UI antes (o snapshot corrigirá se falhar, mas dá sensação de rapidez)
    // Na verdade, com onSnapshot, é melhor esperar ou confiar na velocidade do Firestore.
    // Vamos deixar o Firestore propagar a mudança.
    try {
      const clientRef = doc(db, 'users', loggedUser.id, 'clients', id);
      await deleteDoc(clientRef);
    } catch (error) {
      console.error("Erro ao deletar cliente:", error);
      alert("Erro ao excluir. Verifique sua conexão.");
    }
  }, [loggedUser]);

  const handleEditClient = useCallback((c: Client) => {
    setEditingClient(c);
    setIsModalOpen(true);
  }, []);

  const handleSaveClient = useCallback(async (clientData: Client) => {
    if (!loggedUser) return;

    try {
      const clientRef = doc(db, 'users', loggedUser.id, 'clients', clientData.id);
      // setDoc com { merge: true } funciona para Criar (se não existe) e Atualizar (se existe)
      await setDoc(clientRef, clientData, { merge: true });
      setIsModalOpen(false);
    } catch (error) {
      console.error("Erro ao salvar cliente:", error);
      alert("Erro ao salvar dados. Tente novamente.");
    }
  }, [loggedUser]);

  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;
    clients.forEach(c => {
      revenue += c.price || 0;
      const days = getDaysDifference(c.renewalDate);
      if (days >= 0 && days <= 3) expiring++;
    });
    return { totalClients: clients.length, activeRevenue: revenue, expiringSoon: expiring };
  }, [clients]);

  const counts = useMemo(() => {
    const counts = { all: clients.length, active: 0, expiring: 0, expired: 0 };
    clients.forEach(c => {
      const days = getDaysDifference(c.renewalDate);
      if (days < 0) counts.expired++;
      else if (days <= 3) counts.expiring++;
      else counts.active++;
    });
    return counts;
  }, [clients]);

  const filteredClients = useMemo(() => {
    const query = debouncedSearchTerm.toLowerCase();
    return clients
      .filter(c => {
        if (query) {
          const matchesSearch = c.name.toLowerCase().includes(query) || 
                               c.server?.toLowerCase().includes(query) ||
                               c.phone.includes(query) ||
                               c.macAddress?.toLowerCase().includes(query);
          if (!matchesSearch) return false;
        }
        const days = getDaysDifference(c.renewalDate);
        if (filterStatus === 'active') return days > 3;
        if (filterStatus === 'expiring') return days >= 0 && days <= 3;
        if (filterStatus === 'expired') return days < 0;
        return true;
      })
      .sort((a, b) => getDaysDifference(a.renewalDate) - getDaysDifference(b.renewalDate));
  }, [clients, debouncedSearchTerm, filterStatus]);

  if (loadingAuth) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!loggedUser) {
    return (
      <Suspense fallback={<div className="min-h-screen bg-[#020617]" />}>
        <AuthView />
      </Suspense>
    );
  }

  return (
    <div id="conteudo-sistema" className="min-h-screen bg-[#020617] text-slate-200 pb-safe">
      <header className="sticky top-0 z-40 glass border-b border-white/5 pt-[env(safe-area-inset-top)]">
        <div className="max-w-7xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 md:w-10 md:h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-900/40 relative overflow-hidden group">
              <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
              <Tv className="text-white relative z-10" size={18} />
            </div>
            <div className="hidden xs:block">
              <h1 className="text-base md:text-lg font-black tracking-tighter text-white">MANAGER PRO</h1>
              <div className="flex items-center gap-1">
                <p className="text-[9px] text-slate-500 font-bold uppercase tracking-[0.2em]">Dashboard</p>
                <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-bold text-emerald-400 border border-emerald-500/20">
                  <Cloud size={8} /> SALVO
                </div>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 md:gap-6">
            <div className="flex items-center gap-3 pl-3 md:pl-0 border-l md:border-l-0 border-white/5 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => setIsProfileModalOpen(true)}>
               <div className="text-right hidden sm:block">
                 <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest leading-none mb-1">Conta Ativa</p>
                 <p id="user-name" className="text-xs font-bold text-white leading-none truncate max-w-[120px]">{loggedUser.username}</p>
               </div>
               {loggedUser.avatar ? (
                 <img src={loggedUser.avatar} alt="Avatar" className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-indigo-500/30 object-cover shadow-lg" />
               ) : (
                 <div className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-slate-800 border border-white/10 flex items-center justify-center overflow-hidden">
                    <img src={`https://ui-avatars.com/api/?name=${loggedUser.username}&background=4f46e5&color=fff&bold=true`} alt={loggedUser.username} className="w-full h-full object-cover" />
                 </div>
               )}
            </div>

            <div className="flex items-center gap-1">
              <button onClick={handleLogout} className="p-2 text-slate-400 hover:text-rose-400 transition-colors" title="Sair">
                <LogOut size={20} />
              </button>
              <button 
                onClick={() => { setEditingClient(null); setIsModalOpen(true); }} 
                className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2.5 rounded-xl md:rounded-2xl text-[10px] md:text-xs font-black flex items-center gap-2 transition-all active:scale-90 shadow-xl shadow-indigo-900/20"
              >
                <Plus size={16} />
                <span className="hidden sm:inline">NOVO CLIENTE</span>
                <span className="sm:hidden">NOVO</span>
              </button>
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 flex overflow-x-auto scrollbar-hide scroll-ios">
          <button onClick={() => setActiveTab('list')} className={`flex-shrink-0 flex items-center gap-2 px-6 py-4 text-[10px] md:text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'list' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <LayoutDashboard size={14} /> Painel
            {activeTab === 'list' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-500 rounded-full shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
          <button onClick={() => setActiveTab('analytics')} className={`flex-shrink-0 flex items-center gap-2 px-6 py-4 text-[10px] md:text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'analytics' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <BarChart3 size={14} /> Analytics
            {activeTab === 'analytics' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-500 rounded-full shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 md:px-6 py-6 md:py-10 animate-fade-up scroll-ios">
        <Suspense fallback={<LoadingSpinner />}>
          {activeTab === 'list' ? (
            <>
              <StatsCards stats={stats} />
              <div className="space-y-4 md:space-y-6 mb-8 md:mb-12">
                <div className="relative group">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-500 transition-colors" size={18} />
                  <input 
                    type="text" 
                    placeholder="Pesquisar por nome, MAC ou telefone..." 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    className="w-full bg-slate-900/50 border border-white/5 text-white rounded-2xl md:rounded-[24px] pl-12 pr-12 py-4 md:py-5 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500/30 outline-none transition-all text-base font-medium shadow-inner" 
                  />
                  {searchTerm && (
                    <button onClick={() => setSearchTerm('')} className="absolute right-4 top-1/2 -translate-y-1/2 bg-white/5 hover:bg-white/10 p-2 rounded-xl transition-all">
                      <X size={14} className="text-slate-400" />
                    </button>
                  )}
                </div>

                <div className="flex flex-nowrap overflow-x-auto gap-2 md:gap-3 items-center p-1.5 rounded-[20px] md:rounded-[24px] bg-slate-900/40 border border-white/5 scrollbar-hide scroll-ios">
                  <FilterTab active={filterStatus === 'all'} onClick={() => setFilterStatus('all')} label="Todos" count={counts.all} color="indigo" />
                  <FilterTab active={filterStatus === 'active'} onClick={() => setFilterStatus('active')} label="Ativos" count={counts.active} color="emerald" />
                  <FilterTab active={filterStatus === 'expiring'} onClick={() => setFilterStatus('expiring')} label="Aviso" count={counts.expiring} color="amber" />
                  <FilterTab active={filterStatus === 'expired'} onClick={() => setFilterStatus('expired')} label="Fim" count={counts.expired} color="rose" />
                </div>
              </div>

              {loadingData ? (
                 <LoadingSpinner />
              ) : filteredClients.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
                  {filteredClients.map(client => (
                    <ClientCard 
                      key={client.id} 
                      client={client} 
                      daysUntilExpiration={getDaysDifference(client.renewalDate)} 
                      onDelete={handleDeleteClient} 
                      onEdit={handleEditClient}
                      onRenew={handleRenewClient}
                    />
                  ))}
                </div>
              ) : (
                <div className="text-center py-16 md:py-24 glass rounded-[32px] md:rounded-[40px] border-dashed border-2 border-white/5">
                  <div className="w-16 h-16 md:w-20 md:h-20 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-6">
                    <Search size={24} className="text-slate-500" />
                  </div>
                  <h3 className="text-xl md:text-2xl font-bold text-white mb-3">Nenhum registro</h3>
                  <p className="text-slate-500 max-w-xs mx-auto text-sm">Ajuste seus filtros ou adicione um novo cliente. Seus dados estão salvos na nuvem.</p>
                </div>
              )}
            </>
          ) : <AnalyticsView clients={clients} />}
        </Suspense>
      </main>

      <div className="h-[env(safe-area-inset-bottom)]"></div>

      <Suspense fallback={null}>
        <ClientModal 
          isOpen={isModalOpen} 
          onClose={() => setIsModalOpen(false)} 
          onSave={handleSaveClient} 
          editingClient={editingClient} 
        />
        <UserProfileModal
          isOpen={isProfileModalOpen}
          onClose={() => setIsProfileModalOpen(false)}
          user={loggedUser}
          onUpdate={setLoggedUser}
          onLogout={handleLogout}
        />
      </Suspense>
    </div>
  );
};

const FilterTab = React.memo(({ active, onClick, label, count, color }: {active: boolean, onClick: () => void, label: string, count: number, color: string}) => {
  const colorMap: any = {
    indigo: active ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:bg-white/5',
    emerald: active ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:bg-white/5',
    amber: active ? 'bg-amber-600 text-white' : 'text-slate-500 hover:bg-white/5',
    rose: active ? 'bg-rose-600 text-white' : 'text-slate-500 hover:bg-white/5'
  };
  return (
    <button onClick={onClick} className={`flex-shrink-0 flex items-center gap-2 px-4 md:px-6 py-2 md:py-3 rounded-xl md:rounded-2xl text-[9px] md:text-[11px] font-black uppercase tracking-widest transition-all ${colorMap[color]} active:scale-95`}>
      {label}
      <span className={`px-1.5 py-0.5 rounded-lg ${active ? 'bg-black/20' : 'bg-slate-800'}`}>{count}</span>
    </button>
  );
});

export default App;

import React, { useState, useEffect, useMemo, useCallback, Suspense, lazy } from 'react';
import { Client, ClientStats, User as UserType } from './types';
import { Plus, Search, Tv, LayoutDashboard, BarChart3, LogOut, X, Loader2, Cloud, Signal } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { 
  auth, 
  onAuthStateChanged, 
  signOut, 
  db, 
  doc, 
  getDoc, 
  setDoc,
  collection,
  query,
  onSnapshot,
  updateDoc,
  deleteDoc,
  writeBatch
} from './services/firebase';
import { UserProfileModal } from './components/UserProfileModal';

// Lazy loading components
const ClientModal = lazy(() => import('./components/ClientModal').then(m => ({ default: m.ClientModal })));
const AnalyticsView = lazy(() => import('./components/AnalyticsView').then(m => ({ default: m.AnalyticsView })));
const AuthView = lazy(() => import('./components/AuthView').then(m => ({ default: m.AuthView })));

// Helper movido para fora do componente para performance
const getDaysDifference = (dateString: string): number => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const targetDate = new Date(dateString);
  targetDate.setHours(0, 0, 0, 0);
  const diffTime = targetDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const LoadingSpinner = () => (
  <div className="flex flex-col items-center justify-center py-20 gap-4">
    <Loader2 size={32} className="text-indigo-500 animate-spin" />
    <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Sincronizando dados...</p>
  </div>
);

const App: React.FC = () => {
  const [loggedUser, setLoggedUser] = useState<UserType | null>(null);
  const [loadingAuth, setLoadingAuth] = useState(true);
  const [loadingData, setLoadingData] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'expiring' | 'expired'>('all');

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearchTerm(searchTerm);
    }, 300);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  // 1. Monitoramento de Autenticação
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user: any) => {
      if (user) {
        try {
          const userRef = doc(db, "users", user.uid);
          const userSnap = await getDoc(userRef);

          if (userSnap.exists()) {
            const userData = userSnap.data();
            setLoggedUser({
              id: user.uid,
              username: userData.username || user.displayName || 'User',
              email: userData.email || user.email || '',
              avatar: userData.photoURL || user.photoURL || undefined
            });
          } else {
            const newUserData = {
              username: user.displayName || user.email?.split('@')[0] || 'User',
              email: user.email,
              photoURL: user.photoURL,
              createdAt: new Date().toISOString()
            };
            await setDoc(userRef, newUserData);
            setLoggedUser({
              id: user.uid,
              username: newUserData.username,
              email: newUserData.email,
              avatar: newUserData.photoURL || undefined
            });
          }
        } catch (error) {
          console.error("Error fetching user data:", error);
          setLoggedUser({
            id: user.uid,
            username: user.displayName || 'User',
            email: user.email || '',
            avatar: user.photoURL || undefined
          });
        }
      } else {
        setLoggedUser(null);
        setClients([]);
      }
      setLoadingAuth(false);
    });

    return () => unsubscribe();
  }, []);

  // 2. Sincronização em Tempo Real (Firestore) + Migração de LocalStorage
  useEffect(() => {
    if (!loggedUser) return;

    setLoadingData(true);

    const clientsRef = collection(db, 'users', loggedUser.id, 'clients');
    const q = query(clientsRef);

    const unsubscribe = onSnapshot(q, async (snapshot) => {
      const firebaseClients = snapshot.docs.map(doc => ({ 
        id: doc.id, 
        ...doc.data() 
      })) as Client[];

      // LÓGICA DE MIGRAÇÃO OTIMIZADA
      if (firebaseClients.length === 0) {
        const storageKey = `iptv_data_user_${loggedUser.id}`;
        const localData = localStorage.getItem(storageKey);

        if (localData) {
          try {
            const parsedLocalClients = JSON.parse(localData) as Client[];
            if (parsedLocalClients.length > 0) {
              const batch = writeBatch(db);
              parsedLocalClients.forEach(client => {
                const docRef = doc(clientsRef, client.id);
                batch.set(docRef, client);
              });
              await batch.commit();
            }
          } catch (e) {
            console.error("Erro ao migrar dados locais:", e);
          }
        }
      }

      setClients(firebaseClients);
      setLoadingData(false);
    }, (error) => {
      console.error("Erro no listener do Firestore:", error);
      setLoadingData(false);
    });

    return () => unsubscribe();
  }, [loggedUser]);

  const handleLogout = useCallback(async () => {
    try {
      await signOut(auth);
      setLoggedUser(null);
    } catch (error) {
      console.error("Erro ao sair:", error);
    }
  }, []);

  const handleRenewClient = useCallback(async (id: string) => {
    if (!loggedUser) return;

    const clientToRenew = clients.find(c => c.id === id);
    if (!clientToRenew) return;

    const today = new Date();
    const currentRenewal = new Date(clientToRenew.renewalDate);
    // Lógica inteligente: se já venceu, renova a partir de hoje. Se não venceu, soma 30 dias na data atual de vencimento.
    let newDate = currentRenewal < today ? new Date(today) : new Date(currentRenewal);
    newDate.setDate(newDate.getDate() + 30);
    const newDateStr = newDate.toISOString().split('T')[0];

    try {
      const clientRef = doc(db, 'users', loggedUser.id, 'clients', id);
      await updateDoc(clientRef, { renewalDate: newDateStr });
    } catch (error) {
      console.error("Erro ao renovar cliente:", error);
      alert("Erro ao salvar renovação. Verifique sua conexão.");
    }
  }, [clients, loggedUser]);

  const handleDeleteClient = useCallback(async (id: string) => {
    if (!loggedUser) return;
    if (!confirm("Tem certeza que deseja excluir este cliente?")) return;

    try {
      const clientRef = doc(db, 'users', loggedUser.id, 'clients', id);
      await deleteDoc(clientRef);
    } catch (error) {
      console.error("Erro ao deletar cliente:", error);
      alert("Erro ao excluir. Verifique sua conexão.");
    }
  }, [loggedUser]);

  const handleEditClient = useCallback((c: Client) => {
    setEditingClient(c);
    setIsModalOpen(true);
  }, []);

  const handleSaveClient = useCallback(async (clientData: Client) => {
    if (!loggedUser) return;

    try {
      const clientRef = doc(db, 'users', loggedUser.id, 'clients', clientData.id);
      await setDoc(clientRef, clientData, { merge: true });
      setIsModalOpen(false);
    } catch (error) {
      console.error("Erro ao salvar cliente:", error);
      alert("Erro ao salvar dados. Tente novamente.");
    }
  }, [loggedUser]);

  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;
    clients.forEach(c => {
      revenue += c.price || 0;
      const days = getDaysDifference(c.renewalDate);
      if (days >= 0 && days <= 3) expiring++;
    });
    return { totalClients: clients.length, activeRevenue: revenue, expiringSoon: expiring };
  }, [clients]);

  const counts = useMemo(() => {
    const counts = { all: clients.length, active: 0, expiring: 0, expired: 0 };
    clients.forEach(c => {
      const days = getDaysDifference(c.renewalDate);
      if (days < 0) counts.expired++;
      else if (days <= 3) counts.expiring++;
      else counts.active++;
    });
    return counts;
  }, [clients]);

  const filteredClients = useMemo(() => {
    const queryStr = debouncedSearchTerm.toLowerCase();

    let result = clients;

    // Filtro de Texto
    if (queryStr) {
      result = result.filter(c => 
        c.name.toLowerCase().includes(queryStr) || 
        c.server?.toLowerCase().includes(queryStr) ||
        c.phone.includes(queryStr) ||
        c.macAddress?.toLowerCase().includes(queryStr)
      );
    }

    // Filtro de Status
    result = result.filter(c => {
      const days = getDaysDifference(c.renewalDate);
      if (filterStatus === 'active') return days > 3;
      if (filterStatus === 'expiring') return days >= 0 && days <= 3;
      if (filterStatus === 'expired') return days < 0;
      return true;
    });

    // Ordenação: Vencendo primeiro
    return result.sort((a, b) => getDaysDifference(a.renewalDate) - getDaysDifference(b.renewalDate));
  }, [clients, debouncedSearchTerm, filterStatus]);

  if (loadingAuth) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!loggedUser) {
    return (
      <Suspense fallback={<div className="min-h-screen bg-[#020617]" />}>
        <AuthView />
      </Suspense>
    );
  }

  return (
    <div id="conteudo-sistema" className="min-h-screen bg-[#020617] text-slate-200 pb-safe relative">
      {/* Background Dinâmico - Toque Premium */}
      <div className="fixed inset-0 pointer-events-none z-0">
         <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/10 blur-[120px] rounded-full mix-blend-screen opacity-50 animate-pulse" style={{animationDuration: '8s'}}></div>
         <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-emerald-900/10 blur-[120px] rounded-full mix-blend-screen opacity-30 animate-pulse" style={{animationDuration: '10s'}}></div>
      </div>

      <header className="sticky top-0 z-40 glass border-b border-white/5 pt-[env(safe-area-inset-top)] backdrop-blur-xl">
        <div className="max-w-7xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between relative z-10">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 md:w-10 md:h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-900/40 relative overflow-hidden group">
              <div className="absolute inset-0 bg-gradient-to-tr from-white/0 via-white/20 to-white/0 translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
              <Tv className="text-white relative z-10" size={18} />
            </div>
            <div className="hidden xs:block">
              <h1 className="text-base md:text-lg font-black tracking-tighter text-white">MANAGER PRO</h1>
              <div className="flex items-center gap-1">
                <p className="text-[9px] text-slate-500 font-bold uppercase tracking-[0.2em]">Dashboard</p>
                <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-bold text-emerald-400 border border-emerald-500/20">
                  <Signal size={8} className="animate-pulse" /> ONLINE
                </div>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 md:gap-6">
            <div className="flex items-center gap-3 pl-3 md:pl-0 border-l md:border-l-0 border-white/5 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => setIsProfileModalOpen(true)}>
               <div className="text-right hidden sm:block">
                 <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest leading-none mb-1">Conta Ativa</p>
                 <p id="user-name" className="text-xs font-bold text-white leading-none truncate max-w-[120px]">{loggedUser.username}</p>
               </div>
               {loggedUser.avatar ? (
                 <img src={loggedUser.avatar} alt="Avatar" className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-indigo-500/30 object-cover shadow-lg" />
               ) : (
                 <div className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-slate-800 border border-white/10 flex items-center justify-center overflow-hidden">
                    <img src={`https://ui-avatars.com/api/?name=${loggedUser.username}&background=4f46e5&color=fff&bold=true`} alt={loggedUser.username} className="w-full h-full object-cover" />
                 </div>
               )}
            </div>

            <div className="flex items-center gap-1">
              <button onClick={handleLogout} className="p-2 text-slate-400 hover:text-rose-400 transition-colors" title="Sair">
                <LogOut size={20} />
              </button>
              <button 
                onClick={() => { setEditingClient(null); setIsModalOpen(true); }} 
                className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2.5 rounded-xl md:rounded-2xl text-[10px] md:text-xs font-black flex items-center gap-2 transition-all active:scale-90 shadow-xl shadow-indigo-900/20 hover:shadow-indigo-900/40"
              >
                <Plus size={16} />
                <span className="hidden sm:inline">NOVO CLIENTE</span>
                <span className="sm:hidden">NOVO</span>
              </button>
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 flex overflow-x-auto scrollbar-hide scroll-ios relative z-10">
          <button onClick={() => setActiveTab('list')} className={`flex-shrink-0 flex items-center gap-2 px-6 py-4 text-[10px] md:text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'list' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <LayoutDashboard size={14} /> Painel
            {activeTab === 'list' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-indigo-500 shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
          <button onClick={() => setActiveTab('analytics')} className={`flex-shrink-0 flex items-center gap-2 px-6 py-4 text-[10px] md:text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'analytics' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <BarChart3 size={14} /> Analytics
            {activeTab === 'analytics' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-indigo-500 shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 md:px-6 py-6 md:py-10 animate-fade-up scroll-ios relative z-10">
        <Suspense fallback={<LoadingSpinner />}>
          {activeTab === 'list' ? (
            <>
              <StatsCards stats={stats} />
              <div className="space-y-4 md:space-y-6 mb-8 md:mb-12">
                <div className="relative group">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-500 transition-colors" size={18} />
                  <input 
                    type="text" 
                    placeholder="Pesquisar por nome, MAC ou telefone..." 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    className="w-full bg-slate-900/50 border border-white/5 text-white rounded-2xl md:rounded-[24px] pl-12 pr-12 py-4 md:py-5 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500/30 outline-none transition-all text-base font-medium shadow-inner" 
                  />
                  {searchTerm && (
                    <button onClick={() => setSearchTerm('')} className="absolute right-4 top-1/2 -translate-y-1/2 bg-white/5 hover:bg-white/10 p-2 rounded-xl transition-all">
                      <X size={14} className="text-slate-400" />
                    </button>
                  )}
                </div>

                <div className="flex flex-nowrap overflow-x-auto gap-2 md:gap-3 items-center p-1.5 rounded-[20px] md:rounded-[24px] bg-slate-900/40 border border-white/5 scrollbar-hide scroll-ios">
                  <FilterTab active={filterStatus === 'all'} onClick={() => setFilterStatus('all')} label="Todos" count={counts.all} color="indigo" />
                  <FilterTab active={filterStatus === 'active'} onClick={() => setFilterStatus('active')} label="Ativos" count={counts.active} color="emerald" />
                  <FilterTab active={filterStatus === 'expiring'} onClick={() => setFilterStatus('expiring')} label="Aviso" count={counts.expiring} color="amber" />
                  <FilterTab active={filterStatus === 'expired'} onClick={() => setFilterStatus('expired')} label="Fim" count={counts.expired} color="rose" />
                </div>
              </div>

              {loadingData ? (
                 <LoadingSpinner />
              ) : filteredClients.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8 pb-20">
                  {filteredClients.map(client => (
                    <ClientCard 
                      key={client.id} 
                      client={client} 
                      daysUntilExpiration={getDaysDifference(client.renewalDate)} 
                      onDelete={handleDeleteClient} 
                      onEdit={handleEditClient}
                      onRenew={handleRenewClient}
                    />
                  ))}
                </div>
              ) : (
                <div className="text-center py-16 md:py-24 glass rounded-[32px] md:rounded-[40px] border-dashed border-2 border-white/5">
                  <div className="w-16 h-16 md:w-20 md:h-20 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-6">
                    <Search size={24} className="text-slate-500" />
                  </div>
                  <h3 className="text-xl md:text-2xl font-bold text-white mb-3">Nenhum registro</h3>
                  <p className="text-slate-500 max-w-xs mx-auto text-sm">Ajuste seus filtros ou adicione um novo cliente. Seus dados estão salvos na nuvem.</p>
                </div>
              )}
            </>
          ) : <AnalyticsView clients={clients} />}
        </Suspense>
      </main>

      <Suspense fallback={null}>
        <ClientModal 
          isOpen={isModalOpen} 
          onClose={() => setIsModalOpen(false)} 
          onSave={handleSaveClient} 
          editingClient={editingClient} 
        />
        <UserProfileModal
          isOpen={isProfileModalOpen}
          onClose={() => setIsProfileModalOpen(false)}
          user={loggedUser}
          onUpdate={setLoggedUser}
          onLogout={handleLogout}
        />
      </Suspense>
    </div>
  );
};

const FilterTab = React.memo(({ active, onClick, label, count, color }: {active: boolean, onClick: () => void, label: string, count: number, color: string}) => {
  const colorMap: any = {
    indigo: active ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500 hover:bg-white/5',
    emerald: active ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'text-slate-500 hover:bg-white/5',
    amber: active ? 'bg-amber-600 text-white shadow-lg shadow-amber-500/20' : 'text-slate-500 hover:bg-white/5',
    rose: active ? 'bg-rose-600 text-white shadow-lg shadow-rose-500/20' : 'text-slate-500 hover:bg-white/5'
  };
  return (
    <button onClick={onClick} className={`flex-shrink-0 flex items-center gap-2 px-4 md:px-6 py-2 md:py-3 rounded-xl md:rounded-2xl text-[9px] md:text-[11px] font-black uppercase tracking-widest transition-all ${colorMap[color]} active:scale-95 border border-transparent ${active ? '' : 'hover:border-white/5'}`}>
      {label}
      <span className={`px-1.5 py-0.5 rounded-lg ${active ? 'bg-black/20' : 'bg-slate-800'}`}>{count}</span>
    </button>
  );
});

export default App;

import React, { useState, useEffect } from 'react';
import { Client } from '../types';
import { X, Save, User, Smartphone, Server, FileText, Calendar, CreditCard, Cpu, Key, Tv, Monitor, Copy, Check } from 'lucide-react';

interface ClientModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  editingClient: Client | null;
}

const emptyClient: Omit<Client, 'id'> = {
  name: '',
  phone: '',
  startDate: new Date().toISOString().split('T')[0],
  renewalDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  price: 35.00,
  devices: 1,
  notes: '',
  server: '',
  macAddress: '',
  devicePassword: '',
  deviceType: 'other'
};

export const ClientModal: React.FC<ClientModalProps> = ({ isOpen, onClose, onSave, editingClient }) => {
  const [formData, setFormData] = useState<Omit<Client, 'id'>>(emptyClient);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (editingClient) {
      setFormData({
        name: editingClient.name,
        phone: editingClient.phone,
        startDate: editingClient.startDate.split('T')[0],
        renewalDate: editingClient.renewalDate.split('T')[0],
        price: editingClient.price,
        devices: editingClient.devices,
        notes: editingClient.notes || '',
        server: editingClient.server || '',
        macAddress: editingClient.macAddress || '',
        devicePassword: editingClient.devicePassword || '',
        deviceType: editingClient.deviceType || 'other'
      });
    } else {
      setFormData(emptyClient);
    }
  }, [editingClient, isOpen]);

  // Função para aplicar máscara de telefone (BR)
  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, ''); // Remove não dígitos

    // Limita a 11 dígitos
    if (value.length > 11) value = value.substring(0, 11);

    // Aplica a máscara (XX) XXXXX-XXXX
    if (value.length > 2) {
      value = `(${value.substring(0, 2)}) ${value.substring(2)}`;
    }
    if (value.length > 10) {
      value = `${value.substring(0, 10)}-${value.substring(10)}`;
    }

    setFormData({...formData, phone: value});
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      id: editingClient ? editingClient.id : crypto.randomUUID(),
    });
    onClose();
  };

  const handleCopyData = () => {
    const lines = [
      `👤 *NOME:* ${formData.name}`,
      `📱 *WHATSAPP:* ${formData.phone}`,
      `📅 *VENCIMENTO:* ${new Date(formData.renewalDate).toLocaleDateString('pt-BR')}`,
      `💰 *VALOR:* R$ ${formData.price.toFixed(2)}`,
      formData.server ? `📺 *SERVIDOR:* ${formData.server}` : null,
      formData.macAddress ? `📟 *MAC:* ${formData.macAddress}` : null,
      formData.devicePassword ? `🔑 *SENHA:* ${formData.devicePassword}` : null,
      formData.notes ? `📝 *OBS:* ${formData.notes}` : null,
    ];

    const text = lines.filter(Boolean).join('\n');
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const DeviceOption = ({ type, label, icon: Icon }: { type: 'android' | 'iphone' | 'tv' | 'other', label: string, icon: any }) => {
    const isSelected = formData.deviceType === type;
    return (
      <button
        type="button"
        onClick={() => setFormData({ ...formData, deviceType: type })}
        className={`flex-1 flex flex-col items-center justify-center gap-2 py-3 px-2 rounded-2xl border transition-all ${
          isSelected 
            ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-900/40' 
            : 'bg-slate-950/40 border-white/5 text-slate-500 hover:bg-white/5 hover:text-slate-300'
        }`}
      >
        <Icon size={20} />
        <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
      </button>
    );
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-300 pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]">
      <div className="glass border-white/10 rounded-[32px] md:rounded-[40px] w-full max-w-2xl shadow-3xl overflow-hidden animate-in zoom-in-95 duration-300 max-h-[90vh] flex flex-col">
        <div className="px-6 md:px-8 py-4 md:py-6 border-b border-white/5 flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 md:w-10 md:h-10 bg-indigo-500/20 rounded-xl flex items-center justify-center">
              <User className="text-indigo-400" size={18} />
            </div>
            <h2 className="text-xl md:text-2xl font-extrabold text-white tracking-tight">
              {editingClient ? 'Editar Cliente' : 'Novo Registro'}
            </h2>
          </div>

          <div className="flex gap-2">
            <button 
              type="button"
              onClick={handleCopyData}
              className={`w-9 h-9 md:w-10 md:h-10 flex items-center justify-center rounded-full transition-all active:scale-90 border border-white/5 ${copied ? 'bg-emerald-500/20 text-emerald-400' : 'bg-slate-800/50 text-slate-400 hover:text-white hover:bg-slate-700'}`}
              title="Copiar dados do cliente"
            >
              {copied ? <Check size={18} /> : <Copy size={18} />}
            </button>
            <button onClick={onClose} className="w-9 h-9 md:w-10 md:h-10 flex items-center justify-center text-slate-500 hover:text-white hover:bg-white/5 rounded-full transition-all active:scale-90">
              <X size={20} />
            </button>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 md:p-8 space-y-6 md:space-y-8 overflow-y-auto scroll-ios flex-1">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
            {/* Dados Pessoais */}
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Nome do Cliente</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="text"
                  required
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all font-medium text-base placeholder:text-slate-600"
                  placeholder="Nome completo"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">WhatsApp</label>
              <div className="relative group">
                <Smartphone className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="tel"
                  required
                  value={formData.phone}
                  onChange={handlePhoneChange}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all font-medium text-base placeholder:text-slate-600"
                  placeholder="(DDD) 9XXXX-XXXX"
                  maxLength={15}
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Data Início</label>
              <div className="relative group">
                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="date"
                  required
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none text-base"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Próxima Renovação</label>
              <div className="relative group">
                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-400/50 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="date"
                  required
                  value={formData.renewalDate}
                  onChange={e => setFormData({...formData, renewalDate: e.target.value})}
                  className="w-full bg-slate-950/40 border border-indigo-500/20 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-indigo-400 focus:ring-2 focus:ring-indigo-500/30 outline-none font-bold text-base"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Preço (R$)</label>
              <div className="relative group">
                <CreditCard className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="number"
                  step="0.01"
                  required
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none font-bold text-base placeholder:text-slate-600"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Servidor / Painel</label>
              <div className="relative group">
                <Server className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="text"
                  value={formData.server}
                  onChange={e => setFormData({...formData, server: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all uppercase font-bold text-base placeholder:text-slate-600"
                  placeholder="P2P, Gold..."
                />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Dispositivo Principal</label>
            <div className="flex gap-2">
              <DeviceOption type="android" label="Android" icon={Smartphone} />
              <DeviceOption type="iphone" label="iPhone" icon={Smartphone} />
              <DeviceOption type="tv" label="TV / Box" icon={Tv} />
              <DeviceOption type="other" label="Outro" icon={Monitor} />
            </div>
          </div>

          <div className="w-full h-px bg-white/5 my-2"></div>

          {/* Dados Técnicos / Acesso */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
             <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Endereço MAC</label>
              <div className="relative group">
                <Cpu className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="text"
                  value={formData.macAddress}
                  onChange={e => setFormData({...formData, macAddress: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all font-mono text-sm uppercase placeholder:text-slate-600"
                  placeholder="00:1A:2B:3C:4D:5E"
                />
              </div>
            </div>

             <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Senha Dispositivo</label>
              <div className="relative group">
                <Key className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
                <input
                  type="text"
                  value={formData.devicePassword}
                  onChange={e => setFormData({...formData, devicePassword: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-3.5 md:py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all font-medium text-base placeholder:text-slate-600"
                  placeholder="Senha de acesso"
                />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Observações Privadas</label>
            <div className="relative group">
              <FileText className="absolute left-4 top-4 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={16} />
              <textarea
                value={formData.notes}
                onChange={e => setFormData({...formData, notes: e.target.value})}
                className="w-full bg-slate-950/40 border border-white/5 rounded-3xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all h-28 resize-none font-medium text-base placeholder:text-slate-600"
                placeholder="Login, detalhes adicionais..."
              />
            </div>
          </div>

          <div className="pt-4 flex flex-col sm:flex-row justify-end gap-3 pb-4">
             <button
              type="button"
              onClick={onClose}
              className="w-full sm:w-auto px-8 py-4 rounded-2xl text-slate-400 hover:text-white hover:bg-white/5 transition-all text-[10px] font-black uppercase tracking-widest active:scale-95"
            >
              Cancelar
            </button>
            <button
              type="submit"
              className="w-full sm:w-auto bg-indigo-600 hover:bg-indigo-500 text-white px-10 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-2xl shadow-indigo-900/40 active:scale-95 hover:shadow-indigo-500/20"
            >
              <Save size={18} />
              Salvar Registro
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Client } from '../types';
import { Calendar, Smartphone, DollarSign, MessageCircle, Trash2, Edit, Wand2, Copy, Check, UserCheck, Clock, AlertCircle, StickyNote, ExternalLink, Zap, Cpu, Key, Tv, Monitor } from 'lucide-react';
import { generateRenewalMessage } from '../services/geminiService';

interface ClientCardProps {
  client: Client;
  daysUntilExpiration: number;
  onDelete: (id: string) => void;
  onEdit: (client: Client) => void;
  onRenew: (id: string) => void;
}

export const ClientCard: React.FC<ClientCardProps> = ({ client, daysUntilExpiration, onDelete, onEdit, onRenew }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedMsg, setGeneratedMsg] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [successAnimation, setSuccessAnimation] = useState(false);

  const [macCopied, setMacCopied] = useState(false);
  const [passCopied, setPassCopied] = useState(false);

  useEffect(() => {
    if (successAnimation) {
      const timer = setTimeout(() => setSuccessAnimation(false), 2500);
      return () => clearTimeout(timer);
    }
  }, [successAnimation]);

  // Status Logic
  let statusTheme = {
    border: "border-emerald-500/20 hover:border-emerald-500/40",
    bg: "bg-emerald-500/5",
    badge: "bg-emerald-500/10 text-emerald-400",
    text: "Ativo",
    icon: UserCheck
  };

  if (daysUntilExpiration < 0) {
    statusTheme = {
      border: "border-rose-500/20 hover:border-rose-500/40",
      bg: "bg-rose-500/5",
      badge: "bg-rose-500/10 text-rose-400",
      text: "Vencido",
      icon: AlertCircle
    };
  } else if (daysUntilExpiration <= 3) {
    statusTheme = {
      border: "border-amber-500/20 hover:border-amber-500/40",
      bg: "bg-amber-500/5",
      badge: "bg-amber-500/10 text-amber-400",
      text: "Vencendo",
      icon: Clock
    };
  }

  const handleGenerateMessage = async () => {
    setIsGenerating(true);
    setGeneratedMsg(null);
    const msg = await generateRenewalMessage(client);
    setGeneratedMsg(msg);
    setIsGenerating(false);
  };

  const copyToClipboard = () => {
    if (generatedMsg) {
      navigator.clipboard.writeText(generatedMsg);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const copyField = (text: string, setter: React.Dispatch<React.SetStateAction<boolean>>) => {
      navigator.clipboard.writeText(text);
      setter(true);
      setTimeout(() => setter(false), 1500);
  };

  const handleRenewClick = () => {
    setSuccessAnimation(true);
    onRenew(client.id);
  };

  const sendWhatsApp = () => {
    if (!client.phone) return;
    const cleanPhone = client.phone.replace(/\D/g, '');
    const text = generatedMsg ? encodeURIComponent(generatedMsg) : "";
    window.open(`https://wa.me/55${cleanPhone}?text=${text}`, '_blank');
  };

  // Device Info Helper com cores mais vivas
  const getDeviceIcon = () => {
    switch (client.deviceType) {
      case 'tv': return <Tv size={12} className="text-white" />;
      case 'android': return <Smartphone size={12} className="text-emerald-400" />;
      case 'iphone': return <Smartphone size={12} className="text-white" />;
      case 'other': return <Monitor size={12} className="text-slate-300" />;
      default: return null;
    }
  };

  const getDeviceLabel = () => {
    switch (client.deviceType) {
      case 'tv': return 'TV/Box';
      case 'android': return 'Android';
      case 'iphone': return 'iPhone';
      case 'other': return 'Outro';
      default: return null;
    }
  };

  return (
    <div className={`glass rounded-3xl border ${successAnimation ? 'border-emerald-500/60 shadow-[0_0_30px_rgba(16,185,129,0.2)]' : statusTheme.border} p-6 transition-all duration-300 group hover:shadow-2xl relative overflow-hidden h-full flex flex-col`}>

      {/* Background Flash Animation on Renew */}
      {successAnimation && (
        <div className="absolute inset-0 bg-emerald-500/10 animate-pulse z-0 pointer-events-none"></div>
      )}

      <div className="flex justify-between items-start mb-6 relative z-10">
        <div className="flex gap-4">
          <div className={`p-3 rounded-2xl ${successAnimation ? 'bg-emerald-500/20 text-emerald-400' : statusTheme.bg} border border-white/5 text-white/80 transition-colors duration-500`}>
             {successAnimation ? <Check size={24} /> : <statusTheme.icon size={24} />}
          </div>
          <div>
            <h3 className="text-xl font-bold text-white tracking-tight leading-tight truncate max-w-[160px]">
              {client.name}
            </h3>
            <div className="flex gap-1.5 mt-1.5">
              <span className={`inline-block text-[10px] uppercase font-black px-2 py-0.5 rounded-full transition-colors duration-500 ${successAnimation ? 'bg-emerald-500/20 text-emerald-400' : statusTheme.badge}`}>
                {successAnimation ? "RENOVADO" : statusTheme.text}
              </span>

              {client.deviceType && (
                <span className="inline-flex items-center gap-1.5 bg-slate-800/80 border border-white/10 px-2 py-0.5 rounded-full text-[10px] font-bold text-slate-300 uppercase shadow-sm">
                  {getDeviceIcon()}
                  {getDeviceLabel()}
                </span>
              )}
            </div>
          </div>
        </div>

        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
          <button 
            onClick={(e) => {
              e.stopPropagation();
              onEdit(client);
            }}
            className="p-2 text-slate-500 hover:text-white hover:bg-white/5 rounded-xl transition-all"
            title="Editar"
          >
            <Edit size={18} />
          </button>
          <button 
            onClick={(e) => {
              e.stopPropagation();
              onDelete(client.id);
            }}
            className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-400/5 rounded-xl transition-all"
            title="Excluir"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="space-y-3 mb-6 relative z-10 flex-grow">
        <div className="flex items-center justify-between text-sm">
          <span className="text-slate-500 font-medium flex items-center gap-2">
            <Calendar size={14} /> Expiração
          </span>
          <span className={`font-semibold transition-colors duration-500 ${successAnimation ? 'text-emerald-400 scale-105 origin-right' : 'text-slate-200'}`}>
            {new Date(client.renewalDate).toLocaleDateString('pt-BR')}
          </span>
        </div>
        <div className="flex items-center justify-between text-sm">
          <span className="text-slate-500 font-medium flex items-center gap-2">
            <DollarSign size={14} /> Valor
          </span>
          <span className="text-emerald-400 font-bold">
            R$ {client.price.toFixed(2)}
          </span>
        </div>
        <div className="flex items-center justify-between text-sm">
          <span className="text-slate-500 font-medium flex items-center gap-2">
            <Smartphone size={14} /> Telas
          </span>
          <span className="text-slate-200 font-semibold">{client.devices} dispositivo(s)</span>
        </div>
        {client.server && (
          <div className="flex items-center justify-between text-sm">
            <span className="text-slate-500 font-medium flex items-center gap-2">
              <ExternalLink size={14} /> Servidor
            </span>
            <span className="text-indigo-400 font-semibold px-2 py-0.5 bg-indigo-500/10 rounded-lg border border-indigo-500/20 uppercase text-[10px] tracking-wider">
              {client.server}
            </span>
          </div>
        )}
      </div>

      {/* Seção de Dados do Dispositivo (Mac e Senha) */}
      {(client.macAddress || client.devicePassword) && (
        <div className="mb-6 p-3 bg-slate-900/50 rounded-2xl border border-white/5 space-y-2 relative z-10">
          {client.macAddress && (
            <div className="flex items-center justify-between group/mac">
               <div className="flex items-center gap-2 text-slate-500">
                  <Cpu size={14} />
                  <span className="text-[10px] font-black uppercase tracking-wider">MAC</span>
               </div>
               <button 
                onClick={() => copyField(client.macAddress!, setMacCopied)}
                className="flex items-center gap-2 text-xs font-mono text-slate-300 hover:text-white transition-colors"
                title="Copiar MAC"
               >
                 {client.macAddress}
                 {macCopied ? <Check size={12} className="text-emerald-400"/> : <Copy size={12} className="opacity-0 group-hover/mac:opacity-100 transition-opacity"/>}
               </button>
            </div>
          )}
          {client.devicePassword && (
            <div className="flex items-center justify-between group/pass">
               <div className="flex items-center gap-2 text-slate-500">
                  <Key size={14} />
                  <span className="text-[10px] font-black uppercase tracking-wider">Senha</span>
               </div>
               <button 
                onClick={() => copyField(client.devicePassword!, setPassCopied)}
                className="flex items-center gap-2 text-xs font-medium text-slate-300 hover:text-white transition-colors"
                title="Copiar Senha"
               >
                 {client.devicePassword}
                 {passCopied ? <Check size={12} className="text-emerald-400"/> : <Copy size={12} className="opacity-0 group-hover/pass:opacity-100 transition-opacity"/>}
               </button>
            </div>
          )}
        </div>
      )}

      {client.notes && (
        <div className="mb-6 p-3.5 bg-slate-950/40 rounded-2xl border border-white/5 flex gap-3 relative z-10">
          <StickyNote size={14} className="text-indigo-500 shrink-0 mt-1" />
          <p className="text-xs text-slate-400 italic leading-relaxed line-clamp-2 hover:line-clamp-none transition-all cursor-default">
            {client.notes}
          </p>
        </div>
      )}

      <div className="pt-4 border-t border-white/5 space-y-3 relative z-10 mt-auto">
        {/* Lógica de Exibição do Botão de Renovação */}
        {(daysUntilExpiration <= 3 && !successAnimation) ? (
          <button
            onClick={handleRenewClick}
            className="w-full bg-gradient-to-r from-emerald-500 to-teal-600 hover:from-emerald-400 hover:to-teal-500 text-white py-3.5 rounded-2xl flex items-center justify-center gap-2 text-sm font-black uppercase tracking-wider transition-all shadow-xl shadow-emerald-900/30 active:scale-[0.98] animate-pulse"
          >
            <Zap size={18} fill="currentColor" />
            RENOVAR AGORA
          </button>
        ) : successAnimation ? (
           <div className="w-full bg-emerald-500/20 border border-emerald-500/30 text-emerald-400 py-3 rounded-2xl flex items-center justify-center gap-2 text-sm font-bold animate-in fade-in zoom-in-95 duration-300">
              <Check size={18} />
              Renovado com Sucesso!
           </div>
        ) : null}

        {!generatedMsg && !successAnimation && (
           <div className="flex gap-2">
             <button
              onClick={handleGenerateMessage}
              disabled={isGenerating}
              className="flex-1 bg-slate-800 hover:bg-slate-700 text-white py-3 px-4 rounded-2xl flex items-center justify-center gap-2 text-xs font-bold transition-all disabled:opacity-50 active:scale-[0.97] hover:shadow-lg"
             >
               {isGenerating ? (
                 <span className="animate-pulse">Criando...</span>
               ) : (
                 <>
                   <Wand2 size={14} />
                   Cobrança IA
                 </>
               )}
             </button>
              <button 
                onClick={() => {
                  const cleanPhone = client.phone.replace(/\D/g, '');
                  window.open(`https://wa.me/55${cleanPhone}`, '_blank');
                }}
                className="bg-emerald-600 hover:bg-emerald-500 text-white p-3 rounded-2xl transition-all active:scale-[0.97] hover:shadow-lg hover:shadow-emerald-900/20"
                title="Abrir WhatsApp"
              >
                <MessageCircle size={20} />
              </button>
           </div>
        )}

        {generatedMsg && !successAnimation && (
          <div className="bg-slate-900/80 rounded-2xl p-4 border border-indigo-500/20 animate-in fade-in zoom-in-95">
            <p className="text-slate-300 text-xs whitespace-pre-line mb-4 border-l-2 border-indigo-500 pl-3 italic">
              {generatedMsg}
            </p>
            <div className="flex flex-wrap gap-2">
              <button
                onClick={copyToClipboard}
                className="flex-1 bg-white/10 hover:bg-white/20 text-white py-2 rounded-xl flex items-center justify-center gap-2 text-[11px] font-bold transition-all"
              >
                {copied ? <Check size={14} className="text-emerald-400" /> : <Copy size={14} />}
                {copied ? "Pronto!" : "Copiar"}
              </button>
              <button
                onClick={sendWhatsApp}
                className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white py-2 rounded-xl flex items-center justify-center gap-2 text-[11px] font-bold transition-all"
              >
                <MessageCircle size={14} />
                Enviar
              </button>
              <button 
                 onClick={() => setGeneratedMsg(null)}
                 className="w-full mt-2 text-slate-500 hover:text-white text-[10px] font-bold uppercase tracking-widest text-center"
              >
                Cancelar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
